<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/autoload.php';
use Gda\ClientArea\ClientContext;
use Gda\Modules\Caixas\Repositories\CycleRepository;
use Gda\Modules\Caixas\Services\CycleManagementService;
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec("CREATE TABLE cycles(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER,name TEXT,status TEXT DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE participants(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER,name TEXT);CREATE TABLE cycle_participants(cycle_id INTEGER,participant_id INTEGER);CREATE TABLE cycle_points(cycle_id INTEGER,day INTEGER,participant_id INTEGER);CREATE TABLE contributions(cycle_id INTEGER,participant_id INTEGER);CREATE TABLE payouts(cycle_id INTEGER,participant_id INTEGER);CREATE TABLE payment_receipts(cycle_id INTEGER,participant_id INTEGER);CREATE TABLE message_queue(cycle_id INTEGER);CREATE TABLE message_templates(cycle_id INTEGER);");
$repo=new CycleRepository($db,new ClientContext(1));$service=new CycleManagementService($db,$repo);$checks=0;$assert=function(bool$ok,string$msg)use(&$checks){if(!$ok)throw new RuntimeException($msg);$checks++;};
$newCycle=function(int$company,string$name)use($db):array{$db->prepare("INSERT INTO cycles(company_id,name,status)VALUES(?,?,'active')")->execute([$company,$name]);$cycle=(int)$db->lastInsertId();$db->prepare("INSERT INTO participants(company_id,name)VALUES(?,'Administração')")->execute([$company]);$admin=(int)$db->lastInsertId();$db->prepare('INSERT INTO cycle_participants VALUES(?,?)')->execute([$cycle,$admin]);$db->prepare('INSERT INTO cycle_points VALUES(?,1,?)')->execute([$cycle,$admin]);return[$cycle,$admin];};
[$empty,$emptyAdmin]=$newCycle(1,'Vazio');$assert($service->canDeleteCycle($empty),'Caixa vazio não liberado.');$nextAfterLast=$service->deleteEmptyCycle($empty);$assert($nextAfterLast===null,'Último caixa vazio selecionou caixa indevido.');$assert((int)$db->query("SELECT COUNT(*) FROM cycles WHERE id=$empty")->fetchColumn()===0,'Caixa vazio não removido.');$assert((int)$db->query("SELECT COUNT(*) FROM participants WHERE id=$emptyAdmin")->fetchColumn()===0,'Administração exclusiva vazia não removida.');
foreach(['participant','contribution','point','payout','receipt','message']as$kind){[$cycle,$admin]=$newCycle(1,$kind);if($kind==='participant'){$db->exec("INSERT INTO participants(company_id,name)VALUES(1,'Real')");$db->prepare('INSERT INTO cycle_participants VALUES(?,?)')->execute([$cycle,(int)$db->lastInsertId()]);}elseif($kind==='point')$db->prepare('INSERT INTO cycle_points VALUES(?,2,?)')->execute([$cycle,$admin]);elseif($kind==='message')$db->prepare('INSERT INTO message_queue VALUES(?)')->execute([$cycle]);else{$table=['contribution'=>'contributions','payout'=>'payouts','receipt'=>'payment_receipts'][$kind];$db->prepare("INSERT INTO $table VALUES(?,?)")->execute([$cycle,$admin]);}$assert(!$service->canDeleteCycle($cycle),"Dependência $kind não bloqueou.");try{$service->deleteEmptyCycle($cycle);$blocked=false;}catch(RuntimeException$e){$blocked=$e->getMessage()==='has_history';}$assert($blocked,"Exclusão com $kind não foi rejeitada.");}
[$archived]=$newCycle(1,'Arquivar');$assert($service->archiveCycle($archived),'Arquivamento falhou.');$assert($service->reactivateCycle($archived),'Reativação falhou.');$assert($repo->findOwned($archived)['status']==='active','Reativação não persistiu.');
[$foreign]=$newCycle(2,'Outra empresa');$assert(!$service->canDeleteCycle($foreign),'Caixa de outra empresa foi liberado.');try{$service->deleteEmptyCycle($foreign);$foreignBlocked=false;}catch(RuntimeException$e){$foreignBlocked=$e->getMessage()==='not_found';}$assert($foreignBlocked,'Caixa de outra empresa foi excluído.');
echo "Cycle management tests: $checks checks passed\n";
